import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cam_qtp_02_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_qtp_02", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.032082312649278e+00, -2.972837755986191e+00, -2.889850511503518e+00, -2.774949959292480e+00, -2.618495060069918e+00, -2.410470135853244e+00, -2.143042669315918e+00, -1.814985855594484e+00, -1.436878386251610e+00, -1.031823904535480e+00, -6.347207924175533e-01, -4.080660623192699e-01, -3.432180761949718e-01, -2.627091160400782e-01, -1.535796153467957e-01, -5.054837418043982e-02, -9.187952411560630e-04, -9.877278038271545e-04, -7.408786999326063e-05, -1.749032781676388e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


